def priority(item: float, bins: np.ndarray) -> np.ndarray:
    utilization = (bins - item) / bins
    ideal_utilization = 0.5
    deviation = np.abs(utilization - ideal_utilization)
    return 1 / (deviation + 1e-8)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    utilization = (bins - item) / bins
    ideal_utilization = 0.6
    deviation = np.abs(utilization - ideal_utilization)
    return 1 / (np.log(1 + deviation) + 1e-8)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.minimum(bins, item)
    return remaining
